<div class="page-header"><div><span class="eyebrow">EVERY NUMBER IS SOMEONE’S NEXT CHAPTER</span><h1>People behind the progress.</h1><p>Manage accounts thoughtfully. Keep learning records and permissions in the right hands.</p></div><span class="icon-tile blue"><?= icon('users',24) ?></span></div><div class="toolbar"><form action="<?= e(route_url(route_path())) ?>" class="filter-form" method="get"><div class="search-field"><?= icon('search',17) ?><input type="search" name="q" value="<?= e($_GET['q']??'') ?>" maxlength="150" placeholder="Find a name or email…" aria-label="Search learners"></div><select class="select" name="status" aria-label="Account status"><option value="">All accounts</option><option value="active" <?= ($_GET['status']??'')==='active'?'selected':'' ?>>Active</option><option value="suspended" <?= ($_GET['status']??'')==='suspended'?'selected':'' ?>>Suspended</option></select><button class="btn btn-secondary"><?= icon('filter',14) ?> Filter learners</button></form><span class="results-label"><?= number($total) ?> accounts</span></div><section class="card table-card"><?php if($users): ?><div class="table-responsive"><table class="data-table"><thead><tr><th>Learner</th><th>Role</th><th>Status</th><th>Email</th><th>Joined</th><th></th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><div class="table-person"><span class="avatar"><?= e(initials($u['full_name'])) ?></span><div><strong><?= e($u['full_name']) ?></strong><small><?= e($u['email']) ?></small></div></div></td><td><?= badge($u['role']) ?></td><td><?= badge($u['status']) ?></td><td><?= badge($u['email_verified_at']?'verified':'unverified') ?></td><td><?= niceDate($u['created_at'],'M j, Y') ?></td><td><a class="icon-button" href="<?= e(route_url('/admin/users/' . ((int)$u['id']))) ?>" aria-label="View <?= e($u['full_name']) ?>"><?= icon('arrow-up-right',17) ?></a></td></tr><?php endforeach; ?></tbody></table></div><?php pagination($total); ?><?php else: emptyState('users','No matching accounts.','Try a different search or status filter. No learner records have been invented.','/admin/users','Show every account');endif; ?></section>
